   112→export function stackToDesktopSegments(
   113→  stack: BreadcrumbStackItem[] | undefined
   114→): DesktopBreadcrumbSegment[] {
   115→  if (!stack || stack.length <= 1) {
   116→    return [];
   117→  }
   118→
   119→  return stack.slice(1).map((item) => ({
   120→    id: item.id,
   121→    label: item.label,
   122→    href: item.target?.canonicalUrl ?? "#",
   123→    icon: item.icon,
   124→    descriptorId: item.descriptorId,
   125→    meta: item.meta,
   126→  }));
   127→}
   128→
   129→export function buildFallbackDesktopSegment(input: {
