   131→  label: string;
   132→  location: DesktopLocation;
   133→  descriptorId: string;
   134→  icon?: IconData;
   135→  meta?: DesktopBreadcrumbSegment["meta"];
   136→}): DesktopBreadcrumbSegment {
   137→  const item = createBreadcrumbItem({
   138→    id: input.id,
   139→    label: input.label,
   140→    location: input.location,
   141→    descriptorId: input.descriptorId,
   142→    icon: input.icon,
   143→    meta: input.meta,
   144→  });
   145→
   146→  return {
   147→    id: item.id,
   148→    label: item.label,
   149→    href: item.target?.canonicalUrl ?? "#",
   150→    icon: item.icon,
   151→    descriptorId: item.descriptorId,
   152→    meta: item.meta,
   153→  };
   154→}
