   156→export function buildWorkspaceSectionHeaderSegment(
   157→  workspaceId: string,
   158→  section: WorkspaceSection,
   159→  buildLabel?: (titleKey: string, fallbackLabel: string) => string
   160→): DesktopBreadcrumbSegment {
   161→  const descriptor = getWorkspaceSectionDescriptor(section);
   162→  const routePath = descriptor?.routePath ?? section;
   163→
   164→  return {
   165→    id: `workspace:${workspaceId}:${section}`,
   166→    label: descriptor
   167→      ? buildLabel?.(descriptor.titleKey, descriptor.fallbackLabel) ??
   168→        descriptor.fallbackLabel
   169→      : section,
   170→    href: `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`,
   171→    icon: descriptor?.icon,
   172→    descriptorId: `workspace-section:${section}`,
   173→    meta: {
   174→      workspaceId,
   175→      section,
   176→      routePath,
   177→    },
   178→  };
   179→}
   180→
   181→export function resolveHeaderSegments(input: {
   182→  stack?: BreadcrumbStackItem[];
   183→  fallback?: DesktopBreadcrumbSegment[];
   184→  patchLast?: Partial<DesktopBreadcrumbSegment> & {
   185→    meta?: DesktopBreadcrumbSegment["meta"];
   186→  };
   187→}): DesktopBreadcrumbSegment[] {
   188→  const stackSegments = stackToDesktopSegments(input.stack);
   189→  const patchLast = input.patchLast;
   190→
   191→  if (stackSegments.length === 0) {
   192→    return input.fallback ?? [];
   193→  }
   194→
   195→  if (!patchLast) {
   196→    return stackSegments;
   197→  }
   198→
   199→  return stackSegments.map((segment, index, segments) =>
   200→    index === segments.length - 1
   201→      ? {
   202→          ...segment,
   203→          ...patchLast,
   204→          meta: {
   205→            ...segment.meta,
   206→            ...patchLast.meta,
   207→          },
   208→        }
   209→      : segment
   210→  );
   211→}
