   213→export function createWorkspaceRootNode(
   214→  workspaceId: string,
   215→  label = "Workspace"
   216→): VirtualPageIndexNode {
   217→  return {
   218→    id: `workspace:${workspaceId}`,
   219→    descriptorId: "workspace",
   220→    label,
   221→    icon: { type: "lucide", value: "folder-open" },
   222→    order: 0,
   223→    isContainer: true,
   224→  };
   225→}
