   484→  const pageItems = buildDropdownItems(
   485→    pages.filter((page) => !page.slug.includes("/")),
   486→    (page) => ({
   487→      id: `workspace:${workspaceId}:page:${page.slug}`,
   488→      label: page.name,
   489→      href: `/workspace/${encodeURIComponent(workspaceId)}/page/${page.slug
   490→        .split("/")
   491→        .filter(Boolean)
   492→        .map((segment) => encodeURIComponent(segment))
   493→        .join("/")}`,
   494→      icon: page.icon,
   495→      isActive:
   496→        currentPageSlug === page.slug ||
   497→        Boolean(currentPageSlug?.startsWith(`${page.slug}/`)),
   498→      descriptorId: "workspace-page",
   499→      meta: {
   500→        workspaceId,
   501→        pageSlug: page.slug,
   502→      },
   503→    })
   504→  );
   505→
   506→  return pageItems.length > 0
   507→    ? [...sectionItems, { id: `workspace:${workspaceId}:apps-pages-separator`, label: "", separator: true }, ...pageItems]
   508→    : sectionItems;
   509→}
