   648→        input.segment.href.startsWith("/settings/") &&
   649→        input.segment.label === getSettingsSectionLabel(),
   650→      build: (input) =>
   651→        buildRootDropdownItems({
   652→          workspaces: input.workspaces,
   653→          currentArea: input.currentArea,
   654→          activeWorkspaceId: input.activeWorkspaceId,
   655→          currentSection: input.currentSection,
   656→          activeHref: input.segment.href,
   657→          buildLabel: input.buildLabel,
   658→          onSelectWorkspace: input.onSelectWorkspace,
   659→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   660→        }),
   661→    },
   662→    {
