   716→        const parentPrefix = currentSlug.includes("/")
   717→          ? currentSlug.slice(0, currentSlug.lastIndexOf("/") + 1)
   718→          : "";
   719→        const depth = parentPrefix ? parentPrefix.split("/").filter(Boolean).length + 1 : 1;
   720→
   721→        const siblings = (input.pages ?? []).filter((page) => {
   722→          // Same depth and same parent prefix
   723→          const pageDepth = page.slug.split("/").filter(Boolean).length;
   724→          if (pageDepth !== depth) return false;
   725→          if (parentPrefix) {
   726→            return page.slug.startsWith(parentPrefix);
   727→          }
   728→          return !page.slug.includes("/");
