   732→          id: `workspace:${wId}:page:${page.slug}`,
   733→          label: page.name,
   734→          href: `/workspace/${encodeURIComponent(wId)}/page/${page.slug
   735→            .split("/")
   736→            .filter(Boolean)
   737→            .map((s) => encodeURIComponent(s))
   738→            .join("/")}`,
   739→          icon: page.icon,
   740→          isActive: page.slug === currentSlug,
   741→          descriptorId: "workspace-page",
   742→          meta: {
   743→            workspaceId: wId,
   744→            pageSlug: page.slug,
   745→          },
   746→        }));
   747→      },
   748→    },
   749→  ];
   750→
   751→  const matchedRule = rules.find((rule) => rule.matches(input, descriptorId));
   752→
   753→  if (matchedRule) {
   754→    return matchedRule.build(input);
   755→  }
   756→
   757→  return [];
   758→}
